	/** Collapsible URL inventory read from manifest.json (the scraped URL list). */
	private function render_inventory( array $cfg ) {
		$m = $this->manifest( $cfg );
		if ( ! $m ) {
			return;
		}
		$pages = isset( $m['pages'] ) ? (array) $m['pages'] : array();
		if ( ! $pages ) {
			return;
		}
		?>
		<details style="margin:1.5em 0;">
			<summary style="cursor:pointer;font-weight:600;">
				<?php
				printf(
					/* translators: %d: number of URLs in the captured inventory */
					esc_html__( 'URL inventory (%d paths)', 'binary-wp-admin-guide' ),
					(int) count( $pages )
				);
				?>
			</summary>
			<table class="widefat striped" style="margin-top:8px;max-width:1100px;">
				<thead>
					<tr>
						<th><?php esc_html_e( 'Path', 'binary-wp-admin-guide' ); ?></th>
						<th><?php esc_html_e( 'Type', 'binary-wp-admin-guide' ); ?></th>
						<th><?php esc_html_e( 'Section', 'binary-wp-admin-guide' ); ?></th>
						<th><?php esc_html_e( 'Source HTTP', 'binary-wp-admin-guide' ); ?></th>
						<th><?php esc_html_e( 'Target HTTP', 'binary-wp-admin-guide' ); ?></th>
						<th title="<?php esc_attr_e( 'Target page height minus source page height (px)', 'binary-wp-admin-guide' ); ?>">Δ <?php esc_html_e( 'height', 'binary-wp-admin-guide' ); ?></th>
					</tr>
				</thead>
				<tbody>
					<?php foreach ( $pages as $p ) :
						$prod  = isset( $p['prod'] ) && is_array( $p['prod'] ) ? $p['prod'] : array();
						$local = isset( $p['local'] ) && is_array( $p['local'] ) ? $p['local'] : array();
						$ph    = isset( $prod['height'] ) ? (int) $prod['height'] : 0;
						$lh    = isset( $local['height'] ) ? (int) $local['height'] : 0;
						$delta = ( $ph && $lh ) ? ( $lh - $ph ) : null;
					?>
						<tr>
							<td><code><?php echo esc_html( isset( $p['path'] ) ? (string) $p['path'] : '' ); ?></code></td>
							<td><?php echo esc_html( isset( $p['type'] ) ? (string) $p['type'] : '—' ); ?></td>
							<td><?php echo esc_html( isset( $p['section'] ) ? (string) $p['section'] : '—' ); ?></td>
							<td><?php echo esc_html( isset( $prod['status'] ) ? (string) $prod['status'] : '—' ); ?></td>
							<td><?php echo esc_html( isset( $local['status'] ) ? (string) $local['status'] : '—' ); ?></td>
							<td><?php echo esc_html( null === $delta ? '—' : sprintf( '%+d px', $delta ) ); ?></td>
						</tr>
					<?php endforeach; ?>
				</tbody>
			</table>
		</details>
		<?php
	}

	/** Toolbar behavior: regenerate / stop / status poll, gallery reload. */
	private function render_toolbar_script( $ctl_nonce ) {
		$actions = array(
			'regenerate'      => $this->context->action_name( 'compare_regenerate' ),
			'stop'            => $this->context->action_name( 'compare_stop' ),
			'status'          => $this->context->action_name( 'compare_status' ),
			'refresh_sitemap' => $this->context->action_name( 'compare_refresh_sitemap' ),
		);
		?>
		<script>
		(function () {
			const ajaxurl  = <?php echo wp_json_encode( admin_url( 'admin-ajax.php' ) ); ?>;
			const nonce    = <?php echo wp_json_encode( $ctl_nonce ); ?>;
			const actions  = <?php echo wp_json_encode( $actions ); ?>;
			const statusEl = document.getElementById('bwp-compare-status');
			const runBtn   = document.getElementById('bwp-compare-run');
			const stopBtn  = document.getElementById('bwp-compare-stop');
			const modeSel  = document.getElementById('bwp-compare-mode');
			const incChk   = document.getElementById('bwp-compare-incremental');
			const typChk   = document.getElementById('bwp-compare-typical');
			const limitInp = document.getElementById('bwp-compare-limit');
			const smBtn    = document.getElementById('bwp-compare-refresh-sitemap');
			const smEl     = document.getElementById('bwp-compare-source-summary');
			let polling = null;

			function post(action, extra) {
				const body = new URLSearchParams(Object.assign({ action, _ajax_nonce: nonce }, extra || {}));
				return fetch(ajaxurl, { method: 'POST', body }).then(r => r.json());
			}
			function reloadFrame() {
				const f = document.getElementById('bwp-compare-frame');
				if (f) { const u = new URL(f.src); u.searchParams.set('cb', Date.now()); f.src = u.toString(); }
				else { location.reload(); }
			}
			function running(on) {
				if (runBtn) runBtn.disabled = on;
				if (modeSel) modeSel.disabled = on;
				if (incChk) incChk.disabled = on;
				if (typChk) typChk.disabled = on;
				if (smBtn) smBtn.disabled = on;
				if (stopBtn) stopBtn.style.display = on ? '' : 'none';
			}

			// Refresh sitemap data: re-harvest the source sitemap (no capture) so the
			// source count + per-type options reflect the current sitemap. Reloads
			// the page on success so the Source dropdown regenerates server-side.
			if (smBtn) smBtn.addEventListener('click', () => {
				smBtn.disabled = true;
				if (smEl) smEl.textContent = 'refreshing…';
				post(actions.refresh_sitemap).then(res => {
					if (res && res.success) {
						if (smEl) smEl.textContent = res.data.summary || '';
						location.reload();
					} else {
						smBtn.disabled = false;
						if (smEl) smEl.textContent = 'refresh failed: ' + ((res && res.data && res.data.message) || 'error');
					}
				});
			});

			let lastProgress = '';
			function poll() {
				post(actions.status).then(res => {
					if (!res || !res.success) return;
					const d = res.data;
					if (d.running) {
						running(true);
						statusEl.textContent = 'capturing… ' + (d.progress || '');
						// Live progress: refresh the gallery as new shots land, but
						// only when the progress line actually advanced (avoid jank).
						if (d.progress && d.progress !== lastProgress) { lastProgress = d.progress; reloadFrame(); }
					} else {
						statusEl.textContent = d.summary || '';
						clearInterval(polling); polling = null; running(false);
						reloadFrame();
					}
				});
			}
			function startPolling() { if (!polling) polling = setInterval(poll, 3000); }

			if (runBtn) runBtn.addEventListener('click', () => {
				const mode = modeSel ? modeSel.value : 'demo';
				const incremental = incChk ? incChk.checked : true;
				const typical = typChk ? typChk.checked : false;
				const limit = limitInp && limitInp.value ? parseInt(limitInp.value, 10) : 0;
				if (mode === 'full' && !incremental && !typical && !limit && !confirm('Full re-capture of the WHOLE sitemap (not incremental) can take many minutes. Continue?')) return;
				running(true); statusEl.textContent = 'starting ' + mode + (typical ? ' · typical' : '') + (limit ? ' · first ' + limit : '') + (incremental ? ' · incremental' : '') + '…';
				post(actions.regenerate, { mode, incremental: incremental ? '1' : '0', typical: typical ? '1' : '0', limit: String(limit || 0) }).then(res => {
					if (!res || !res.success) { running(false); statusEl.textContent = 'failed: ' + ((res && res.data && res.data.message) || 'error'); return; }
					startPolling();
				});
			});

			if (stopBtn) stopBtn.addEventListener('click', () => {
				stopBtn.disabled = true;
				post(actions.stop).then(() => { stopBtn.disabled = false; poll(); });
			});

			// Button label always reflects the selected source (+ limit) so it's
			// unmistakable what a click will capture.
			function syncBtn() {
				if (!runBtn || !modeSel) return;
				const typ = typChk && typChk.checked ? ' · typical' : '';
				const lim = limitInp && limitInp.value ? ' · first ' + limitInp.value : '';
				runBtn.textContent = '↻ Regenerate — ' + modeSel.options[modeSel.selectedIndex].text + typ + lim;
			}
			if (modeSel) modeSel.addEventListener('change', syncBtn);
			if (limitInp) limitInp.addEventListener('input', syncBtn);
			if (typChk) typChk.addEventListener('change', syncBtn);
			if (modeSel) syncBtn();

			// If a run is already going (started elsewhere / CLI), pick it up on load.
			post(actions.status).then(res => { if (res && res.success && res.data.running) startPolling(); });
		})();
		</script>
		<?php
	}

	// ── Settings save (admin-post) ──────────────────────────────────────

	public function handle_save_settings() {
		if ( ! current_user_can( $this->capability() ) ) {
			wp_die( esc_html__( 'Forbidden', 'binary-wp-admin-guide' ), 403 );
		}
		check_admin_referer( $this->context->nonce_action( 'compare_settings' ) );

		$settings = array();
		foreach ( array( 'source_base', 'source_sitemap', 'target_base' ) as $key ) {
			$raw = isset( $_POST[ $key ] ) ? trim( (string) wp_unslash( $_POST[ $key ] ) ) : '';
			$settings[ $key ] = '' === $raw ? '' : esc_url_raw( $raw );
		}
		// Origins shouldn't carry a trailing slash (paths are absolute, start with /).
		$settings['source_base'] = untrailingslashit( $settings['source_base'] );
		$settings['target_base'] = untrailingslashit( $settings['target_base'] );

		update_option( $this->context->option_key( 'compare' ), $settings, false );

		// Refresh the source inventory (sitemap.json) so the page/type counts
		// reflect the sitemap URL just saved — this is what keeps the "source"
		// info valid over time instead of stranding a stale count from the last
		// capture. Best-effort + synchronous (harvest is a quick XML fetch).
		$cfg     = $this->config();
		$harvest = $this->harvest_command( $cfg );
		if ( $harvest && $this->shell_available() ) {
			@shell_exec( $harvest );
		}

		wp_safe_redirect( add_query_arg(
			array( 'page' => $this->page_slug, 'updated' => '1' ),
			admin_url( 'admin.php' )
		) );
		exit;
	}

	// ── AJAX: refresh the source sitemap inventory (harvest-only) ───────

	/**
	 * Re-harvest the source sitemap and rewrite sitemap.json — no capture, no
	 * browser. Backs the "Refresh sitemap data" button so the source page/type
	 * counts can be brought current on demand.
	 */
	public function ajax_refresh_sitemap() {
		if ( ! current_user_can( $this->capability() ) ) {
			wp_send_json_error( array( 'message' => 'forbidden' ), 403 );
		}
		check_ajax_referer( $this->context->nonce_action( 'compare_ctl' ) );
		@set_time_limit( 120 );

		$cfg = $this->config();
		if ( ! $cfg['ready'] ) {
			wp_send_json_error( array( 'message' => 'capture tool unavailable (' . implode( ', ', $cfg['missing'] ) . ')' ) );
		}
		$harvest = $this->harvest_command( $cfg );
		if ( ! $harvest ) {
			wp_send_json_error( array( 'message' => 'no source sitemap configured' ) );
		}
		if ( ! is_dir( $cfg['out_dir'] ) ) {
			wp_mkdir_p( $cfg['out_dir'] );
		}
		$out  = (string) shell_exec( $harvest );
		$data = $this->sitemap_data( $cfg );
		if ( ! $data ) {
			wp_send_json_error( array( 'message' => 'harvest produced no data', 'raw' => mb_substr( $out, 0, 500 ) ) );
		}
		wp_send_json_success( array(
			'summary' => $this->source_summary( $cfg ),
			'total'   => isset( $data['total'] ) ? (int) $data['total'] : 0,
			'types'   => isset( $data['types'] ) ? (array) $data['types'] : array(),
		) );
	}

	// ── AJAX: refresh a set of paths (both sides) in place ──────────────

	public function ajax_refresh() {
		if ( ! current_user_can( $this->capability() ) ) {
			wp_send_json_error( array( 'message' => 'forbidden' ), 403 );
		}
		check_ajax_referer( $this->context->nonce_action( 'compare_refresh' ) );
		@set_time_limit( 300 );

		$cfg = $this->config();
		if ( ! $cfg['ready'] ) {
			wp_send_json_error( array( 'message' => 'capture tool unavailable (' . implode( ', ', $cfg['missing'] ) . ')' ) );
		}
		$paths = json_decode( isset( $_POST['paths'] ) ? wp_unslash( (string) $_POST['paths'] ) : '[]', true );
		$paths = is_array( $paths ) ? $this->sanitize_paths( $paths ) : array();
		if ( ! $paths ) {
			wp_send_json_error( array( 'message' => 'no valid paths' ) );
		}

		$cmd = sprintf(
			'%s %s --out %s --paths %s 2>/dev/null',
			escapeshellarg( $cfg['node'] ),
			escapeshellarg( $cfg['tool_dir'] . '/refresh-cli.mjs' ),
			escapeshellarg( $cfg['out_dir'] ),
			escapeshellarg( (string) wp_json_encode( $paths ) )
		);
		$out = (string) shell_exec( $cmd );
		$res = json_decode( $out, true );
		if ( ! is_array( $res ) || isset( $res['error'] ) ) {
			wp_send_json_error( array(
				'message' => isset( $res['error'] ) ? $res['error'] : 'refresh failed',
				'raw'     => mb_substr( $out, 0, 500 ),
			) );
		}
		wp_send_json_success( array( 'pages' => isset( $res['pages'] ) ? $res['pages'] : array() ) );
	}

	// ── AJAX: kick off a detached regenerate run ────────────────────────

	public function ajax_regenerate() {
		if ( ! current_user_can( $this->capability() ) ) {
			wp_send_json_error( array( 'message' => 'forbidden' ), 403 );
		}
		check_ajax_referer( $this->context->nonce_action( 'compare_ctl' ) );

		$cfg = $this->config();
		if ( ! $cfg['ready'] ) {
			wp_send_json_error( array( 'message' => 'capture tool unavailable (' . implode( ', ', $cfg['missing'] ) . ')' ) );
		}
		if ( $this->is_running( $cfg ) ) {
			wp_send_json_error( array( 'message' => 'a run is already in progress' ) );
		}

		// `mode` = source set: full | demo | smoke | type:<sitemap-type>.
		// NOTE: validated via regex on the RAW value — sanitize_key() would
		// strip the colon out of `type:x`.
		$mode_raw = isset( $_POST['mode'] ) ? (string) wp_unslash( $_POST['mode'] ) : 'full';
		if ( ! preg_match( '/^(full|demo|smoke|type:[a-z0-9_\-]+)$/', $mode_raw ) ) {
			$mode_raw = 'full';
		}
		$mode = $mode_raw;
		if ( 'demo' === $mode ) {
			$args = '--demo';
		} elseif ( 0 === strpos( $mode, 'type:' ) ) {
			$args = '--types ' . substr( $mode, 5 ); // regex-validated slug, shell-safe
		} elseif ( 'smoke' === $mode ) {
			$args = '--limit 10';
		} else {
			$args = ''; // wrapper default = full sitemap
		}
		$limit = isset( $_POST['limit'] ) ? absint( $_POST['limit'] ) : 0;
		if ( $limit > 0 && 'smoke' !== $mode ) {
			$args = trim( $args . ' --limit ' . $limit );
		}
		$incremental = ! empty( $_POST['incremental'] ) && 'false' !== $_POST['incremental'];
		if ( $incremental ) {
			$args = trim( $args . ' --incremental' );
		}
		// "typical layouts only": one representative per non-page type, all pages.
		$typical = ! empty( $_POST['typical'] ) && 'false' !== $_POST['typical'] && '0' !== (string) $_POST['typical'];
		if ( $typical ) {
			$args = trim( $args . ' --typical' );
		}

		// Saved settings drive the capture: source sitemap (the URL scraper),
		// source origin, target origin, plus the configured output dir.
		$settings = $this->settings();
		if ( '' !== $settings['source_sitemap'] ) {
			$args = trim( $args . ' --sitemap ' . escapeshellarg( $settings['source_sitemap'] ) );
		}
		if ( '' !== $settings['source_base'] ) {
			$args = trim( $args . ' --prod-base ' . escapeshellarg( untrailingslashit( $settings['source_base'] ) ) );
		}
		if ( '' !== $settings['target_base'] ) {
			$args = trim( $args . ' --local-base ' . escapeshellarg( untrailingslashit( $settings['target_base'] ) ) );
		}
		$args = trim( $args . ' --out ' . escapeshellarg( $cfg['out_dir'] ) );

		if ( ! is_dir( $cfg['out_dir'] ) ) {
			wp_mkdir_p( $cfg['out_dir'] );
		}
		$lock = $this->lock_file( $cfg );
		$log  = $this->log_file( $cfg );
		@file_put_contents( $lock, 'starting' ); // claim; the run overwrites with its PID

		// Detached: the inner shell writes its own PID into the lock first (so
		// the status poller can check the process is actually alive — a died
		// run's lock then reads as stale instantly), runs the wrapper, and
		// drops the lock on exit. PATH is set explicitly (node dir + standard
		// bins) and bash is called by absolute path — a detached session can
		// inherit a stripped PATH where even `bash` isn't found.
		$inner = sprintf(
			'echo $$ > %s; export PATH=%s:/usr/local/bin:/usr/bin:/bin:"$PATH"; /bin/bash %s %s > %s 2>&1; rm -f %s',
			escapeshellarg( $lock ),
			escapeshellarg( dirname( $cfg['node'] ) ),
			escapeshellarg( $cfg['wrapper'] ),
			$args,
			escapeshellarg( $log ),
			escapeshellarg( $lock )
		);
		$this->spawn_detached( $inner );

		wp_send_json_success( array( 'started' => true, 'mode' => $mode, 'incremental' => $incremental ) );
	}

	// ── AJAX: stop a running regenerate ─────────────────────────────────

	public function ajax_stop() {
		if ( ! current_user_can( $this->capability() ) ) {
			wp_send_json_error( array( 'message' => 'forbidden' ), 403 );
		}
		check_ajax_referer( $this->context->nonce_action( 'compare_ctl' ) );

		$cfg  = $this->config();
		$lock = $this->lock_file( $cfg );
		$pid  = file_exists( $lock ) ? (int) trim( (string) @file_get_contents( $lock ) ) : 0;
		if ( $this->shell_available() ) {
			// Kill the detached wrapper shell, then sweep the actual capture
			// process (macOS has no setsid, so no process-group kill).
			if ( $pid > 0 ) {
				shell_exec( 'kill -TERM ' . (int) $pid . ' 2>/dev/null' );
			}
			if ( '' !== $cfg['tool_dir'] ) {
				shell_exec( 'pkill -f ' . escapeshellarg( $cfg['tool_dir'] . '/capture.mjs' ) . ' 2>/dev/null' );
			}
		}
		@unlink( $lock );
		wp_send_json_success( array( 'stopped' => true ) );
	}

	// ── AJAX: poll regenerate status + manifest summary ─────────────────

	public function ajax_status() {
		if ( ! current_user_can( $this->capability() ) ) {
			wp_send_json_error( array( 'message' => 'forbidden' ), 403 );
		}
		check_ajax_referer( $this->context->nonce_action( 'compare_ctl' ) );

		$cfg     = $this->config();
		$running = $this->is_running( $cfg );

		// Last capture line from the log as a coarse progress indicator.
		$progress = '';
		$log      = $this->log_file( $cfg );
		if ( $running && file_exists( $log ) ) {
			$lines = array_values( array_filter( array_map( 'trim', (array) @file( $log ) ) ) );
			for ( $i = count( $lines ) - 1; $i >= 0; $i-- ) {
				if ( 0 === strpos( $lines[ $i ], '[' ) || 0 === strpos( $lines[ $i ], 'Reading' ) || 0 === strpos( $lines[ $i ], 'Harvesting' ) ) {
					$progress = $lines[ $i ];
					break;
				}
			}
		}

		wp_send_json_success( array(
			'running'  => $running,
			'progress' => $progress,
			'summary'  => $this->summary( $cfg ),
		) );
	}
}
